// The two name coders against conformance/name-vectors.json (generated by
// cpp/tests/name_conformance_emit.cpp): every row, both coders.
//
//   names:   [text, method_number, method_text, name_number, name_text]
//   numbers: [number, method_text, name_text]

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { isCompressedName, isHashName, methodToNumber, nameToNumber, numberToMethod, numberToName } from '../index.js';

const fixture: { version: number; generator: string; names: [string, string, string, string, string][]; numbers: [string, string, string][] } =
  JSON.parse(readFileSync(new URL('../../../conformance/name-vectors.json', import.meta.url), 'utf8'));

test('name-vectors.json: every name row, the method coder and the name coder', () => {
  assert.equal(fixture.version, 1);
  const count = { names: 0, methodCompressed: 0, methodHashed: 0, methodNone: 0, nameNumbered: 0, nameNone: 0 };
  for (const [text, methodNumber, methodText, nameNumber, nameText] of fixture.names) {
    const label = JSON.stringify(text);
    ++count.names;
    const m = methodToNumber(text);
    assert.equal(String(m), methodNumber, `methodToNumber(${label})`);
    assert.equal(numberToMethod(m), methodText, `numberToMethod(methodToNumber(${label}))`);
    // A number is given only to a name it decodes back to.
    if (m !== 0n) assert.equal(methodToNumber(numberToMethod(m)), m, `${label}: the method number round-trips`);
    if (m === 0n) ++count.methodNone;
    else if (isHashName(m)) ++count.methodHashed;
    else {
      assert.ok(isCompressedName(m), label);
      ++count.methodCompressed;
    }
    const n = nameToNumber(text);
    assert.equal(String(n), nameNumber, `nameToNumber(${label})`);
    assert.equal(numberToName(n), nameText, `numberToName(nameToNumber(${label}))`);
    if (n !== 0n) {
      assert.equal(nameText, text, `${label}: a name's number decodes to the name`);
      ++count.nameNumbered;
    } else ++count.nameNone;
  }
  console.log('name-vectors.json names:', JSON.stringify(count));
  // The file as checked in.
  assert.equal(count.names, 1538);
  assert.equal(count.methodCompressed + count.methodHashed + count.methodNone, 1538);
  assert.equal(count.nameNumbered + count.nameNone, 1538);
  assert.ok(count.methodCompressed > 0 && count.methodHashed > 0 && count.methodNone > 0 && count.nameNumbered > 0 && count.nameNone > 0);
});

test('name-vectors.json: every number row, both decoders', () => {
  let rows = 0;
  for (const [number, methodText, nameText] of fixture.numbers) {
    const n = BigInt(number);
    assert.equal(numberToMethod(n), methodText, `numberToMethod(${number})`);
    assert.equal(numberToName(n), nameText, `numberToName(${number})`);
    ++rows;
  }
  assert.equal(rows, 617);
});

test('names: the rules the fixture pins (cpp/tests/consistency_tests.cpp)', () => {
  // The method coder: compressed only when the number decodes to the name.
  assert.equal(methodToNumber(''), 0n);
  assert.equal(numberToMethod(0n), '');
  for (const name of ['hello', 'transfer', 'balance', 'init', 'get']) {
    const number = methodToNumber(name);
    assert.ok(isCompressedName(number) && number !== 0n, name);
    assert.equal(numberToMethod(number), name);
  }
  // A code that runs past 64 bits used to be cut ("getsymboltyp"): now the hash.
  assert.equal(methodToNumber('getSymbolType'), 0xd55df3070b8758ebn);
  assert.equal(numberToMethod(0xd55df3070b8758ebn), '#hmlnslheseoypnnp');
  assert.equal(methodToNumber('#hmlnslheseoypnnp'), 0xd55df3070b8758ebn);
  assert.ok(isHashName(methodToNumber('getSymbolType')));
  // Case and the symbol of a digit / '_' are the canonical form's.
  assert.equal(methodToNumber('Hello'), methodToNumber('hello'));
  // Malformed '#' text has no number.
  for (const text of ['#', '#abc', '#hmlnslheseoypnn', '#hmlnslheseoypnnpp', '#zzzzzzzzzzzzzzzz', '#HMLNSLHESEOYPNN!', '#eeeeeeeeeeeeeeee'])
    assert.equal(methodToNumber(text), 0n, text);
  // A character outside the alphabet: no number.
  for (const text of ['a b', 'a-b', 'é', 'a.b', '\u0000']) assert.equal(methodToNumber(text), 0n, JSON.stringify(text));

  // The name coder: a bijection between names and their numbers.
  assert.equal(nameToNumber(''), 0n);
  assert.equal(numberToName(0n), '');
  for (const name of ['alice', 'bob', 'a', 'psibase', 'my-app', 'x1']) {
    const number = nameToNumber(name);
    assert.notEqual(number, 0n, name);
    assert.equal(numberToName(number), name);
  }
  assert.equal(nameToNumber('x--b'), 0n);                  // the model has no frequency for '-' after '-'
  assert.equal(nameToNumber('9lives'), 0n);                // starts with a digit
  assert.equal(nameToNumber('-a'), 0n);
  assert.equal(nameToNumber('Alice'), 0n);                 // not in the alphabet
  assert.equal(nameToNumber('a'.repeat(19)), 0n);          // too long
  // A well-formed text whose code needs more than 64 bits has no number
  // either (most texts of 12 or more characters).
  const overflow = fixture.names.filter(([text, , , number]) => /^[a-z][a-z0-9-]{0,17}$/.test(text) && !text.includes('--') && number === '0');
  assert.ok(overflow.length > 0);
  for (const [text] of overflow) assert.equal(nameToNumber(text), 0n, text);
  // Whether a NUMBER is a name's: it encodes back.
  assert.equal(nameToNumber(numberToName(nameToNumber('alice'))), nameToNumber('alice'));
  // Numbers are unsigned 64-bit.
  assert.throws(() => numberToName(-1n), RangeError);
  assert.throws(() => numberToMethod(1n << 64n), RangeError);
});
